    """
    if len(p) == 2:
        p[0] = p[1]
    else:
        p[0] = p[2]

def p_factor(p):
    """
    factor : signed_float X UINT signed_int
           | UINT X UINT signed_int
           | UINT signed_int
           | UINT
           | signed_float
    """
    if len(p) == 5:
        if p[3] != 10:
            raise ValueError("Only base ten exponents are allowed in CDS")
        p[0] = p[1] * 10.0 ** p[4]
    elif len(p) == 3:
        if p[1] != 10:
            raise ValueError("Only base ten exponents are allowed in CDS")
        p[0] = 10.0 ** p[2]
    elif len(p) == 2:
        p[0] = p[1]

